import { makeChoropleth, mergeDataToBoundaries } from "/helpers/atlasMap.ojs";

import { downloadCsvButton, downloadPngButton } from "/helpers/uiComponents.ojs";

import { atlasTable } from "/helpers/atlasTable.ojs";

import {
  adminLevelLabel,
  adminSelect,
  adminSelections,
  adminTranslations,
  countries,
  selectedAdmin0,
  selectedAdmin1,
  selectedAdmin2,
} from "/helpers/adminSelectors.ojs";

import { chartStyle, formatUSD, inputTemplate } from "/helpers/std.ojs";

import { createSqlBindings, sqlAdminAt, sqlAdminWhere } from "/helpers/sql.js";

Language



import { lang as Lang } from "/helpers/lang.js";

general_translations = await FileAttachment("/data/shared/generalTranslations.json").json()

languages = [
  { key: "en", label: "English", locale: "en-US" },
  { key: "fr", label: "Français", locale: "fr-FR" },
]

// Language state lives in the navbar switcher; this cell just subscribes.
langKey = Generators.observe((notify) =&gt; {
  notify(window.atlasLang ?? "en");
  const onChange = (e) =&gt; notify(e.detail);
  window.addEventListener("atlas:lang", onChange);
  return () =&gt; window.removeEventListener("atlas:lang", onChange);
})

language = languages.find((l) =&gt; l.key === langKey) ?? languages[0]

_lang = Lang.lg(language.key)












































import { loadNotebookText, readNotebookConfig } from "/helpers/notebook.js";

notebookConfig = readNotebookConfig()

notebookText = await loadNotebookText(notebookConfig)

nbText = notebookText[language.key]

nbTitle = notebookConfig.title[language.key]

tmpl = (template, values) =&gt;
  Lang.reduceReplaceTemplateItems(
    template,
    Object.entries(values).map(([name, value]) =&gt; ({ name, value }))
  )

Admin selectors

adminControls = () =&gt;
  adminSelect([0, 1, 2], {
    langKey: language.key,
    searchable: { admin1: true, admin2: true },
  })

// The boundaries take `adminSelections` — the selector state — as it comes;
// SQL and the level checks take the same selection as plain names.
selectedNames = [...selectedAdmin0, ...selectedAdmin1, ...selectedAdmin2]

// How the selection is named in prose and file names.
breadcrumb = selectedNames.join(", ") || _lang(adminTranslations.ssa)

// The area one level up, named the way breadcrumb names the selection.
parentName = selectedNames.slice(0, -1).join(", ") || _lang(adminTranslations.ssa)

areaSlug = breadcrumb.toLowerCase().replaceAll(/[^a-z0-9]+/g, "-")

Data

db = await DuckDBClient.of({
  exposure: FileAttachment("/data/vulnerability/notebook_exposure.parquet"),
  urgency: FileAttachment("/data/vulnerability/urgency_index.parquet"),
  enabling: FileAttachment("/data/vulnerability/enabling_vars.parquet"),
  icicle: FileAttachment("/data/vulnerability/vulnerability_icicledata.parquet"),
})

// The tables reach beyond the Atlas — North Africa, islands, an SSA aggregate —
// so queries are scoped to the same countries the selectors offer. These tables
// carry no iso3, which is what sqlAdminWhere would otherwise scope by.
atlasCountries = countries.map((d) =&gt; d.admin0_name)

// Rows one level below the selection: pick a country, list its regions.
adminWhere = (bind) =&gt;
  `${sqlAdminWhere(
    { admin0: selectedAdmin0, admin1: selectedAdmin1 },
    bind
  )} AND admin0_name IN (${bind.list(atlasCountries)})`

// These tables carry a whole-continent row filed under the name 'SSA', so an
// empty selection is that row rather than an absent one.
WHOLE_AREA = ["SSA"]

// The selection's own row.
adminWhereExact = (bind) =&gt;
  sqlAdminAt(
    {
      admin0: selectedAdmin0.length ? selectedAdmin0 : WHOLE_AREA,
      admin1: selectedAdmin1,
      admin2: selectedAdmin2,
    },
    bind
  )

// The same, one level up: a region's country, a country's SSA.
adminWhereParent = (bind) =&gt;
  sqlAdminAt(
    {
      admin0: selectedAdmin1.length ? selectedAdmin0 : WHOLE_AREA,
      admin1: selectedAdmin2.length ? selectedAdmin1 : [],
    },
    bind
  )

// Indicators arrive pre-normalised, so a score is just their mean.
meanNorm = (row) =&gt;
  d3.mean(
    Object.entries(row).filter(([key]) =&gt; key.endsWith("_norm")),
    ([, value]) =&gt; value
  ) ?? null

Boundaries

import { adminBoundariesForSelection, getAdminBoundaries } from "/components/_atlasBoundaries.ojs";

// Levels 0 and 1 are small and always drawn.
atlasBoundaries = await getAdminBoundaries([0, 1])

// Fetch deep geometry only when drill-down needs it.
admin2Boundaries = selectedAdmin1.length ? (await getAdminBoundaries(2)).admin2 : null

// Resolve the drawn level once; every table here reaches admin 2.
adminView = adminBoundariesForSelection({
  boundaries: { ...atlasBoundaries, admin2: admin2Boundaries },
  selection: adminSelections,
})

// A selection at the drawn level marks its unit rather than narrowing the map.
adminHighlight = adminView.selectedAtLevel && {
  filter: (feature) =&gt;
    feature.properties[adminView.selectedAtLevel.field] === adminView.selectedAtLevel.names[0],
}

// Join rows to the boundaries at the drawn level.
featuresFor = (data) =&gt;
  mergeDataToBoundaries({
    boundaries: adminView.boundaries,
    data,
    boundaryKey: (feature) =&gt; adminView.adminKey(feature.properties),
    dataKey: adminView.adminKey,
  }).features

// Name the unit drawn, whatever level that is.
areaChannel = ({
  area: {
    label: adminLevelLabel(adminView.level, _lang),
    value: (d) =&gt;
      [d.properties.admin2_name, d.properties.admin1_name, d.properties.admin0_name]
        .filter(Boolean)
        .join(", "),
  },
})

Shared controls and formatting

viewToggle = (options) =&gt;
  Inputs.radio(options, {
    value: options[0],
    label: _lang(general_translations.vizType.title),
    format: (option) =&gt; _lang(general_translations.vizType[option]),
  })

// One download row per section: the figure when one is on screen, always the data.
downloads = (figure, data, name) =&gt; {
  const filename = `${name}_${areaSlug}`;

  return inputTemplate({ gap: "0.5rem" })(
    [
      figure && downloadPngButton(figure, { filename, label: nbText.General.downloadFigure }),
      downloadCsvButton(data, { filename, label: _lang(general_translations.download) }),
    ].filter(Boolean)
  );
}

// Every section closes with the same heading over its own body.
quickInsight = (body) =&gt; md`### ${nbText.General.quickInsights}

${body}`

usd = formatUSD({ locale: language.locale })

// One ramp per direction, shared by every choropleth: yellow to red as a score
// worsens, green to yellow where a high value is the good outcome.
RAMP_WORSE = ["#f4bb21", "#ec5a47"]

RAMP_BETTER = ["#216729", "#f7d732"]

// Admin columns are named the same in every table view.
adminHeaders = ({
  admin0_name: adminLevelLabel(0, _lang),
  admin1_name: adminLevelLabel(1, _lang),
  admin2_name: adminLevelLabel(2, _lang),
})

import { makeChoropleth, mergeDataToBoundaries } from "/helpers/atlasMap.ojs";

import { downloadPngButton } from "/helpers/uiComponents.ojs";

import { chartStyle, formatNumCompactShort, inputTemplate } from "/helpers/std.ojs";

Language



import { lang as Lang } from "/helpers/lang.js";

general_translations = await FileAttachment("/data/shared/generalTranslations.json").json()

languages = [
  { key: "en", label: "English", locale: "en-US" },
  { key: "fr", label: "Français", locale: "fr-FR" },
]

// Language state lives in the navbar switcher; this cell just subscribes.
langKey = Generators.observe((notify) =&gt; {
  notify(window.atlasLang ?? "en");
  const onChange = (e) =&gt; notify(e.detail);
  window.addEventListener("atlas:lang", onChange);
  return () =&gt; window.removeEventListener("atlas:lang", onChange);
})

language = languages.find((l) =&gt; l.key === langKey) ?? languages[0]

_lang = Lang.lg(language.key)












































import { loadNotebookText, readNotebookConfig } from "/helpers/notebook.js";

notebookConfig = readNotebookConfig()

notebookText = await loadNotebookText(notebookConfig)

nbText = notebookText[language.key]

nbTitle = notebookConfig.title[language.key]

tmpl = (template, values) =&gt;
  Lang.reduceReplaceTemplateItems(
    template,
    Object.entries(values).map(([name, value]) =&gt; ({ name, value }))
  )












































farmSizeLabel = (k) =&gt; nbText.General.farmSizeClasses[k] ?? k
eventLabel = (k) =&gt; nbText.General.events[k] ?? k
lossLabel = (k) =&gt; nbText.LossFunctions.selectors.loss.options[k] ?? k
eventTypeLabel = (k) =&gt; nbText.LossFunctions.selectors.eventType.options[k] ?? k
scenarioLabel = (k) =&gt; nbText.Ensembles.scenarios[k] ?? k
modelLabel = (k) =&gt; nbText.LossByFarmType.selectors.model.options[k] ?? k
thresholdLabel = (k) =&gt; nbText.LossByFarmType.legend.options[k] ?? k

//TODO: country names stay as the raw `nm_slc0` data values — translating them
// needs an nm_slc0 -&gt; iso3 -&gt; data/shared/atlas_countries.json lookup, and the
// aggregate ("Sub-Saharan Africa") has no iso3. Add when a French review asks.

numFormat = formatNumCompactShort({ locale: language.locale })

// Zero means the extreme event never occurred, not "0 farms".
farmCount = (d) =&gt; (d !== 0 ? numFormat(d) : nbText.General.noEvents)

Data

hypq = import("https://cdn.jsdelivr.net/npm/hyparquet@1.26.2/+esm")

hypq_compress = import("https://cdn.jsdelivr.net/npm/hyparquet-compressors/+esm")

// Rewinding is load-bearing, not cosmetic: the source rings wind the other way,
// so d3 reads each polygon as the whole sphere minus the region (geoArea 4π).
turfRewind = (await import("https://cdn.jsdelivr.net/npm/@turf/rewind/+esm")).default























bound_arrayBuf = await FileAttachment("/data/lossDamage/bounds.parquet").arrayBuffer()

loadBounds = async (country) =&gt; {
  const bounds = await hypq.parquetQuery({
    file: bound_arrayBuf,
    compressors: hypq_compress.compressors,
    columns: ["GID_0", "NAME_0", "NAME_1", "nm_slc0", "geometry"],
    filter: !country
      ? null
      : {
          nm_slc0: {
            $eq: country,
          },
        },
  });
  return {
    type: "FeatureCollection",
    features: bounds.map(({ geometry, ...properties }) =&gt; ({
      type: "Feature",
      geometry: turfRewind(geometry, { reverse: true }),
      properties,
    })),
  };
}

boundsCache = new Map()

// Sections 1 and 4 pick a country independently but start on the same one, so
// without this the ~100ms decode+rewind of the 1.4MB boundary file runs twice on
// load and again whenever the two selections coincide. Caching the promise (not
// the result) also collapses the two concurrent first calls into one read.
getBounds = (country) =&gt; {
  if (!boundsCache.has(country)) boundsCache.set(country, loadBounds(country));
  return boundsCache.get(country);
}

fig1_mapBounds = await getBounds(fig1_inputs.country)
fig4_mapBounds = await getBounds(fig4_inputs.country)

