    columns: ["nm_slc0", "farm_sz2", "variable"],
  });

  return {
    country: Array.from(new Set(_data.map((d) =&gt; d.nm_slc0))),
    farm_sz2: Array.from(new Set(_data.map((d) =&gt; d.farm_sz2))),
    variable: Array.from(new Set(_data.map((d) =&gt; d.variable))),
