}
















renderS1_inputs = () =&gt; {
  return Inputs.form(
    {
      country: Inputs.select(fig1_selVars.country, {
        label: nbText.General.country,
        value: "Sub-Saharan Africa",
      }),
      fSize: Inputs.select(fig1_selVars.farm_sz2, {
        label: nbText.General.farmSize,
        value: "All Farms",
        format: farmSizeLabel,
      }),
      time: Inputs.select(fig1_selVars.variable, {
        label: nbText.FarmSize.selectors.time.title,
        value: "Current Farms",
        format: (k) =&gt; nbText.FarmSize.selectors.time.options[k] ?? k,
      }),
    },
    { template: inputTemplate({ gap: "3em" }) }
  );
}







fig1a_filtered = await hypq.parquetQuery({
  file: fig1_arrayBuf,
  compressors: hypq_compress.compressors,
  filter: {
    nm_slc0: {
      $eq: fig1_inputs.country,
    },
    farm_sz2: {
      $eq: fig1_inputs.fSize,
    },
    variable: {
      $eq: fig1_inputs.time,
    },
  },
})

fig1a_spatial = mergeDataToBoundaries({
  boundaries: fig1_mapBounds,
  data: fig1a_filtered,
  boundaryKey: (f) =&gt; adminKey(f.properties),
  dataKey: adminKey,
