4b code

fig4b_byCombo = {
  const rows = await hypq.parquetQuery({
    file: await FileAttachment("/data/lossDamage/fig4b.parquet").arrayBuffer(),
    compressors: hypq_compress.compressors,
    columns: [
      "nm_slc0",
      "farm_sz2",
      "Event",
      "model",
      "year",
      "losstype",
      "threshold",
      "threshold2",
      "cum_sum",
    ],
  });

  const byCombo = new Map();
  for (const row of rows) {
    const key = [row.nm_slc0, row.farm_sz2, row.Event, row.model].join("|");
    const bucket = byCombo.get(key);
    bucket ? bucket.push(row) : byCombo.set(key, [row]);
  }
  return byCombo;
}

// Every combination the section 4 selectors can produce is present here (checked
// against fig4_map_fin_spei12_high.parquet: 2100 combinations on both sides), so a
// miss means the two files have drifted apart and should fail loudly.
fig4b_filtered = fig4b_byCombo.get(
  [fig4_inputs.country, fig4_inputs.fSize, fig4_inputs.event, fig4_inputs.time].join("|")
)
















renderS4b_plot = () =&gt; {
  const domainOrder =
    fig4_inputs.event === "Very Dry"
      ? ["Farms Likely Impacted", "40% lost revenue", "50% lost revenue"]
      : ["Farms Likely Impacted", "30% lost revenue", "40% lost revenue"];
  const tip = nbText.LossByFarmType.tooltip;

  return Plot.plot({
    width,
    height: 420,
    marginLeft: 50,
    style: chartStyle,

    x: {
      label: nbText.LossByFarmType.axis.x,
      tickFormat: "d",
    },

    y: {
      label: nbText.LossByFarmType.axis.y,
      grid: true,
      tickFormat: numFormat,
    },

    fx: {
      label: null,
      tickFormat: (k) =&gt; tip.lossTypes[k] ?? k,
    },

    color: {
      legend: true,
      label: nbText.LossByFarmType.legend.title,
      domain: domainOrder,
      range: ["#4E79A7", "#F28E2C", "#E15759"],
      tickFormat: thresholdLabel,
    },

    marks: [
      Plot.line(fig4b_filtered, {
        x: "year",
        y: "cum_sum",
        fx: "losstype",
        stroke: "threshold",
        strokeWidth: 2,
        opacity: 0.85,
        channels: {
          type: {
            value: (d) =&gt; tip.lossTypes[d.losstype] ?? d.losstype,
            label: tip.lossType,
          },
        },
