        shortTerm: shortTerm,
        longTerm: longTerm,
        delta: shortTerm != null && longTerm != null ? longTerm - shortTerm : null,
        interpretation: classification.interpretation,
        implication: classification.implication,
      };
    })
    .filter((d) =&gt; d.shortTerm != null || d.longTerm != null);

  const sortKey =
    { "Short-term skill": "shortTerm", "Long-term skill": "longTerm" }[s13SortBy] ?? "delta";
  return data.sort(descendingDefined((d) =&gt; d[sortKey]));
}







