function renderS3DumbbellPlot(data) {
  const chartHeight = Math.max(600, data.length * 25);
  const dataWithAccess = data.filter((d) =&gt; isFiniteNumber(d.accessValue));
  const completeData = dataWithAccess.filter((d) =&gt; isFiniteNumber(d.cis_readiness_index));
  const labels = data.map((d) =&gt; d.label);
  const axis = labelAxis(labels, 1200);
  const xDomain = d3.extent(
    data
      .flatMap((d) =&gt; [d.cis_readiness_index, d.accessValue])
      .filter(isFiniteNumber)
      .map(Number)
  );
  const tip = makeS3DumbbellTip();

  return Plot.plot({
    style: chartStyle,
    width: 1200,
    height: chartHeight,
    marginLeft: axis.marginLeft,
    marginRight: 50,
    marginTop: 80,
    marginBottom: 80,
    x: {
      domain: xDomain,
      label: "Value",
      grid: true,
      axis: "top",
    },
    y: {
      label: null,
      domain: labels,
      tickFormat: axis.tickFormat,
    },
    marks: [
      Plot.axisX({ anchor: "bottom", label: "Value" }),
      Plot.link(completeData, {
        x1: "cis_readiness_index",
        x2: "accessValue",
        y1: "label",
        y2: "label",
        stroke: (d) =&gt; {
          if (d.gap == null || isNaN(d.gap)) return "#999999";
          return d.gap &gt; 0.05 ? "#4daf4a" : d.gap &lt; -0.05 ? "#e41a1c" : "#999999";
        },
        strokeWidth: 2,
      }),
      Plot.dot(data, {
        x: "cis_readiness_index",
        y: "label",
        fill: "#377eb8",
        r: 5,
        tip: {
          ...tip,
          format: {
            ...tip.format,
            x: (d) =&gt; `Readiness: ${fmt(d, 3)}`,
          },
        },
      }),
      Plot.dot(dataWithAccess, {
        x: "accessValue",
        y: "label",
        fill: "#ff7f00",
        r: 5,
        stroke: "#ff7f00",
        strokeWidth: 2,
        tip,
      }),
    ],
  });
}

