  if (!selected) return rows;

  const names = new Set(selected.names);
  return rows.filter((row) =&gt; names.has(row[selected.field]));
}

// Null-safe fixed-point formatting.
fmt = (value, decimals = 3) =&gt;
  value == null || Number.isNaN(Number(value)) ? "N/A" : Number(value).toFixed(decimals)

isFiniteNumber = (value) =&gt; value != null && Number.isFinite(Number(value))

descendingDefined = (value) =&gt; (a, b) =&gt; {
  const av = value(a);
  const bv = value(b);
  if (!isFiniteNumber(av)) return isFiniteNumber(bv) ? 1 : 0;
  if (!isFiniteNumber(bv)) return -1;
  return Number(bv) - Number(av);
}

// Use shorter table/export labels than map tooltips.
adminDisplayName = (d, level = currentAdminLevel) =&gt;
  level === 0
    ? d.admin0_name
    : level === 1
    ? `${d.admin1_name}, ${d.admin0_name}`
    : `${d.admin2_name}, ${d.admin1_name}`

// Estimate label width for Plot's left margin, then truncate at a proportional cap.
// Tooltips retain full labels.
labelAxis = (labels, chartWidth, { share = 0.35, minimum = 120 } = {}) =&gt; {
  const perChar = 7;
  const gutter = 12;
  // Avoid spreading thousands of admin-2 label lengths.
  const longest = labels.reduce((n, l) =&gt; Math.max(n, String(l).length), 0);
  const cap = Math.max(minimum, Math.round(chartWidth * share));
  const marginLeft = Math.min(cap, Math.max(minimum, longest * perChar + gutter));
  const fits = Math.floor((marginLeft - gutter) / perChar);

  return {
    marginLeft,
    tickFormat: (label) =&gt; {
      const name = String(label);
      return name.length &gt; fits ? `${name.slice(0, fits - 1)}…` : name;
    },
  };
}

