heatmapMeanMarks = (rows, { x, y, v, avg, xLabel, yLabel, textThreshold = 50 }) =&gt; {
  const cells = rows.map((d) =&gt; ({ x: x(d), y: y(d), v: v(d) }));
  const mean = (subset) =&gt;
    subset.length ? Math.round(d3.mean(subset, (c) =&gt; c.v) * 10) / 10 : null;
  const columns = [...new Set(cells.map((c) =&gt; c.x))];
  const countries = [...new Set(cells.map((c) =&gt; c.y))];
  const means = [
    ...columns.map((xv) =&gt; ({ x: xv, y: avg, v: mean(cells.filter((c) =&gt; c.x === xv)) })),
    ...countries.map((yv) =&gt; ({ x: avg, y: yv, v: mean(cells.filter((c) =&gt; c.y === yv)) })),
    { x: avg, y: avg, v: mean(cells) },
  ].filter((c) =&gt; c.v != null);
  return [
    // The {value, label} channel form names the tip rows; the scales keep
    // label: null, so the axes stay bare. Fill takes its name from the legend.
    Plot.cell([...cells, ...means], {
      x: { value: "x", label: xLabel },
      y: { value: "y", label: yLabel },
      fill: "v",
      inset: 1,
      tip: true,
    }),
    Plot.text(means, {
      x: "x",
      y: "y",
      text: (c) =&gt; c.v,
      fontWeight: "bold",
      fill: (c) =&gt; (c.v &gt;= textThreshold ? "white" : "#222"),
    }),
  ];
}

