heatRows = heatHazard === "human"
  ? wbgtData
  : heatHazardData.filter((d) =&gt; d.hazard === heatHazard)

// Each hazard is a different quantity: WBGT counts days per YEAR above a cutoff,
// NTx days per MONTH of the growing season, THI is an index. Livestock cuts follow
// the standard THI scale (no/mild &lt;79, moderate 79-89, severe &gt;=90) — the bivariate
// palette is 3x3, so no-stress and mild share a class, which is also where the
// fewest units sit. Crop 40°C needs its own breaks because two thirds of units sat
// at or below 0.3 days historically. Women 20/50%.
heatClass = d3.scaleThreshold(
  heatHazard === "human" ? [30, 90]
  : heatHazard === "livestock" ? [79, 90]
  : heatThreshold === 40 ? [0.3, 2]
  : [1, 6],
  d3.range(3),
)

womenClass = d3.scaleThreshold([20, 50], d3.range(3))

// x = women (blue), y = heat (red).
biVarColors = bivariatePalettes.blueRed

// A threshold scale bands NaN into its lowest class, so missing values have to be
// caught before the lookup or they would read as low heat and few women.
biVarColor = (row) =&gt; {
  // Unfilled rather than grey: the palette's own low-low cell is #e8e8e8, so a
  // grey no-data class would be indistinguishable from "low heat, few women".
  if (!Number.isFinite(row?.value) || !Number.isFinite(row?.pct_women_agri)) {
    return "#fff";
  }
  const x = womenClass(row.pct_women_agri);
  const y = heatClass(row.value);
  return biVarColors.find((cell) =&gt; cell.x === x && cell.y === y).color;
}

