roiResults = async () =&gt; {
  const index = await calcCV();
  const data = await crop_adoption();

  const withImpact = data.map((row) =&gt; {
    const key = `${row.admin0_name}|${row.crop}`;
    const avloss = index.get(key) ?? 0; // default to 0 if missing

    const result_w_impact_cis = Math.round(row.result_w_impact * (1 + avloss) * 10) / 10;
    const marginal_cis = Math.round((result_w_impact_cis - row.result_w_impact) * 10) / 10;
    const marginal_impact_cis = (marginal_cis || 0) + (row.marginal_impact || 0);

    return {
      ...row,
      avloss,
      result_w_impact_cis,
      marginal_cis,
      marginal_impact_cis,
    };
  });

  return withImpact.map((d) =&gt; {
    const project_benefit =
      Math.round((d.marginal_impact_cis - d.marginal_impact_cis / bcr) * 10) / 10;
    const cis_impact = options_econPerfWalkthrough.inputCisImpact.value;
    return { ...d, bcr, cis_impact, project_benefit };
  });
}

